/* ============================================
   CommerceForge Dev Docs — Design System
   ============================================ */

/* --- Design Tokens --- */
:root {
  /* Dark mode (default) */
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2333;
  --bg-card: #161b22;
  --bg-card-hover: #1c2531;
  --bg-code: #0d1117;
  --bg-sidebar: #0d1117;
  --bg-overlay: rgba(0, 0, 0, 0.6);

  --border-primary: #21262d;
  --border-secondary: #30363d;
  --border-accent: #475f91;

  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-tertiary: #6e7681;
  --text-inverse: #0d1117;

  --accent-blue: #475f91;
  --accent-blue-hover: #5a74b0;
  --accent-cyan: #00d4ff;
  --accent-cyan-hover: #33ddff;
  --accent-green: #00e676;
  --accent-green-dim: #00c853;
  --accent-purple: #b388ff;
  --accent-orange: #ff9100;
  --accent-pink: #ff4081;

  --cta-gradient: linear-gradient(135deg, #00e676, #00d4ff);

  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.5);
  --shadow-glow: 0 0 20px rgba(0, 230, 118, 0.15);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;

  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', SFMono-Regular, Consolas, 'Liberation Mono', Menlo, monospace;

  --sidebar-width: 260px;
  --sidebar-collapsed-width: 0px;
  --nav-height: 64px;
  --max-width: 1280px;

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: var(--accent-cyan);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--accent-cyan-hover);
}

img {
  max-width: 100%;
  display: block;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.25;
  color: var(--text-primary);
}

h1 { font-size: 2.75rem; letter-spacing: -0.02em; }
h2 { font-size: 2rem; letter-spacing: -0.015em; }
h3 { font-size: 1.5rem; letter-spacing: -0.01em; }
h4 { font-size: 1.25rem; }
h5 { font-size: 1rem; }
h6 { font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.05em; }

p {
  color: var(--text-secondary);
  line-height: 1.7;
}

.text-gradient {
  background: var(--cta-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* --- Container --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.container--narrow {
  max-width: 900px;
}

.container--wide {
  max-width: 1400px;
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-primary);
  z-index: 1000;
  display: flex;
  align-items: center;
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.nav__brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 1.125rem;
  color: var(--text-primary);
  text-decoration: none;
}

.nav__brand-icon {
  width: 32px;
  height: 32px;
  background: var(--cta-gradient);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  color: var(--text-inverse);
  font-weight: 800;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.nav__links a {
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color var(--transition-fast);
  position: relative;
}

.nav__links a:hover,
.nav__links a.active {
  color: var(--text-primary);
}

.nav__links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent-cyan);
  border-radius: 1px;
}

.nav__actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.nav__search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  color: var(--text-tertiary);
  font-size: 0.85rem;
  cursor: pointer;
  transition: border-color var(--transition-fast);
}

.nav__search:hover {
  border-color: var(--border-secondary);
}

.nav__search kbd {
  background: var(--bg-tertiary);
  border: 1px solid var(--border-primary);
  border-radius: 4px;
  padding: 1px 6px;
  font-family: var(--font-mono);
  font-size: 0.75rem;
}

.nav__login {
  padding: 7px 18px;
  background: transparent;
  border: 1px solid var(--border-secondary);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.nav__login:hover {
  background: var(--bg-tertiary);
  border-color: var(--text-tertiary);
}

.nav__hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
}

.nav__hamburger span {
  width: 22px;
  height: 2px;
  background: var(--text-primary);
  border-radius: 1px;
  transition: all var(--transition-fast);
}

/* --- Hero --- */
.hero {
  padding: 120px 0 80px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -25%;
  width: 150%;
  height: 200%;
  background: radial-gradient(ellipse at 30% 20%, rgba(0, 230, 118, 0.06) 0%, transparent 50%),
              radial-gradient(ellipse at 70% 80%, rgba(0, 212, 255, 0.04) 0%, transparent 50%);
  pointer-events: none;
}

.hero__content {
  position: relative;
  max-width: 720px;
}

.hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: rgba(0, 230, 118, 0.1);
  border: 1px solid rgba(0, 230, 118, 0.2);
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--accent-green);
  margin-bottom: 24px;
}

.hero__badge i {
  font-size: 0.9rem;
}

.hero h1 {
  margin-bottom: 20px;
}

.hero__subtitle {
  font-size: 1.15rem;
  line-height: 1.7;
  margin-bottom: 36px;
  max-width: 600px;
}

.hero__ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 22px;
  font-family: var(--font-sans);
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
  border: none;
  text-decoration: none;
}

.btn--primary {
  background: var(--accent-green);
  color: var(--text-inverse);
  box-shadow: var(--shadow-glow);
}

.btn--primary:hover {
  background: var(--accent-green-dim);
  color: var(--text-inverse);
  box-shadow: 0 0 30px rgba(0, 230, 118, 0.25);
}

.btn--secondary {
  background: transparent;
  border: 1px solid var(--border-secondary);
  color: var(--text-primary);
}

.btn--secondary:hover {
  background: var(--bg-tertiary);
  border-color: var(--text-tertiary);
  color: var(--text-primary);
}

.btn--ghost {
  background: transparent;
  color: var(--accent-cyan);
  padding: 10px 0;
}

.btn--ghost:hover {
  color: var(--accent-cyan-hover);
}

.btn--sm {
  padding: 7px 16px;
  font-size: 0.825rem;
}

/* --- Section --- */
.section {
  padding: 80px 0;
}

.section__header {
  margin-bottom: 48px;
}

.section__header h2 {
  margin-bottom: 12px;
}

.section__header p {
  font-size: 1.05rem;
  max-width: 600px;
}

.section--alt {
  background: var(--bg-secondary);
}

/* --- Cards --- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 28px;
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}

.card:hover {
  border-color: var(--border-secondary);
  background: var(--bg-card-hover);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card__icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 18px;
  font-size: 1.3rem;
}

.card__icon--green {
  background: rgba(0, 230, 118, 0.12);
  color: var(--accent-green);
  border: 1px solid rgba(0, 230, 118, 0.15);
}

.card__icon--cyan {
  background: rgba(0, 212, 255, 0.12);
  color: var(--accent-cyan);
  border: 1px solid rgba(0, 212, 255, 0.15);
}

.card__icon--purple {
  background: rgba(179, 136, 255, 0.12);
  color: var(--accent-purple);
  border: 1px solid rgba(179, 136, 255, 0.15);
}

.card__icon--orange {
  background: rgba(255, 145, 0, 0.12);
  color: var(--accent-orange);
  border: 1px solid rgba(255, 145, 0, 0.15);
}

.card__icon--pink {
  background: rgba(255, 64, 129, 0.12);
  color: var(--accent-pink);
  border: 1px solid rgba(255, 64, 129, 0.15);
}

.card__icon--blue {
  background: rgba(71, 95, 145, 0.2);
  color: var(--accent-blue-hover);
  border: 1px solid rgba(71, 95, 145, 0.25);
}

.card h3 {
  font-size: 1.15rem;
  margin-bottom: 10px;
}

.card p {
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 16px;
}

.card__link {
  font-size: 0.875rem;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.card__link i {
  font-size: 0.8rem;
  transition: transform var(--transition-fast);
}

.card:hover .card__link i {
  transform: translateX(3px);
}

/* Product cards - larger, with gradient accent */
.product-card {
  padding: 36px;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
}

.product-card--apps::before {
  background: linear-gradient(90deg, var(--accent-green), var(--accent-cyan));
}

.product-card--storefronts::before {
  background: linear-gradient(90deg, var(--accent-cyan), var(--accent-purple));
}

.product-card--agents::before {
  background: linear-gradient(90deg, var(--accent-purple), var(--accent-pink));
}

.product-card h3 {
  font-size: 1.35rem;
  margin-bottom: 12px;
}

/* Card grids */
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

/* --- Accordion --- */
.accordion {
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-card);
}

.accordion__item {
  border-bottom: 1px solid var(--border-primary);
}

.accordion__item:last-child {
  border-bottom: none;
}

.accordion__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 24px;
  background: transparent;
  border: none;
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition-fast);
  text-align: left;
}

.accordion__trigger:hover {
  background: var(--bg-card-hover);
}

.accordion__trigger i {
  transition: transform var(--transition-base);
  color: var(--text-tertiary);
}

.accordion__item.is-open .accordion__trigger {
  background: var(--bg-card-hover);
  color: var(--accent-cyan);
}

.accordion__item.is-open .accordion__trigger i {
  transform: rotate(180deg);
  color: var(--accent-cyan);
}

.accordion__body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base), padding var(--transition-base);
}

.accordion__item.is-open .accordion__body {
  max-height: 500px;
}

.accordion__content {
  padding: 0 24px 24px;
}

.accordion__step {
  display: flex;
  gap: 16px;
  margin-bottom: 20px;
}

.accordion__step-number {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--accent-cyan);
}

.accordion__step-text {
  padding-top: 3px;
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* --- Tabs (Package Manager) --- */
.tabs {
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-card);
}

.tabs__list {
  display: flex;
  border-bottom: 1px solid var(--border-primary);
  background: var(--bg-secondary);
}

.tabs__tab {
  padding: 12px 24px;
  background: transparent;
  border: none;
  color: var(--text-secondary);
  font-family: var(--font-sans);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
  position: relative;
}

.tabs__tab:hover {
  color: var(--text-primary);
  background: var(--bg-card-hover);
}

.tabs__tab.is-active {
  color: var(--accent-cyan);
}

.tabs__tab.is-active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent-cyan);
}

.tabs__panel {
  display: none;
  padding: 20px 24px;
}

.tabs__panel.is-active {
  display: block;
}

/* --- Code Block --- */
.code-block {
  background: var(--bg-code);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  padding: 16px 20px;
  font-family: var(--font-mono);
  font-size: 0.875rem;
  line-height: 1.7;
  color: var(--text-primary);
  overflow-x: auto;
  position: relative;
}

.code-block .prompt {
  color: var(--accent-green);
  user-select: none;
}

.code-block .command {
  color: var(--text-primary);
}

.code-block .comment {
  color: var(--text-tertiary);
}

.code-block__copy {
  position: absolute;
  top: 10px;
  right: 10px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  padding: 4px 10px;
  font-size: 0.75rem;
  cursor: pointer;
  transition: all var(--transition-fast);
  display: flex;
  align-items: center;
  gap: 4px;
}

.code-block__copy:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

/* --- CLI Setup Section --- */
.cli-setup {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  padding: 48px;
  border: 1px solid var(--border-primary);
}

.cli-setup__header {
  margin-bottom: 36px;
}

.cli-setup__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: start;
}

/* --- Sidebar Layout --- */
.layout {
  display: flex;
  min-height: calc(100vh - var(--nav-height));
  padding-top: var(--nav-height);
}

.sidebar {
  width: var(--sidebar-width);
  background: var(--bg-sidebar);
  border-right: 1px solid var(--border-primary);
  position: fixed;
  top: var(--nav-height);
  left: 0;
  bottom: 0;
  overflow-y: auto;
  transition: width var(--transition-base), transform var(--transition-base);
  z-index: 100;
  padding: 24px 0;
}

.sidebar.is-collapsed {
  width: var(--sidebar-collapsed-width);
  transform: translateX(calc(-1 * var(--sidebar-width)));
}

.sidebar__toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 20px;
  margin-bottom: 16px;
  background: none;
  border: none;
  color: var(--text-secondary);
  font-size: 0.8rem;
  cursor: pointer;
  font-family: var(--font-sans);
  transition: color var(--transition-fast);
  width: 100%;
}

.sidebar__toggle:hover {
  color: var(--text-primary);
}

.sidebar__section {
  margin-bottom: 24px;
}

.sidebar__section-title {
  padding: 0 20px;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-tertiary);
  margin-bottom: 8px;
}

.sidebar__link {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 20px;
  color: var(--text-secondary);
  font-size: 0.875rem;
  transition: all var(--transition-fast);
  text-decoration: none;
}

.sidebar__link:hover {
  color: var(--text-primary);
  background: var(--bg-secondary);
}

.sidebar__link.is-active {
  color: var(--accent-cyan);
  background: rgba(0, 212, 255, 0.06);
  border-right: 2px solid var(--accent-cyan);
}

.sidebar__link i {
  font-size: 1rem;
  width: 20px;
  text-align: center;
}

.main-content {
  flex: 1;
  margin-left: var(--sidebar-width);
  transition: margin-left var(--transition-base);
  min-width: 0;
}

.main-content.is-expanded {
  margin-left: var(--sidebar-collapsed-width);
}

.main-content__inner {
  max-width: 900px;
  margin: 0 auto;
  padding: 48px 40px;
}

/* --- Community Grid --- */
.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.community-card {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition-base);
  text-decoration: none;
  display: block;
}

.community-card:hover {
  border-color: var(--border-secondary);
  background: var(--bg-card-hover);
  transform: translateY(-2px);
}

.community-card i {
  font-size: 1.5rem;
  color: var(--accent-cyan);
  margin-bottom: 14px;
  display: block;
}

.community-card h4 {
  font-size: 0.95rem;
  margin-bottom: 6px;
  color: var(--text-primary);
}

.community-card p {
  font-size: 0.825rem;
  color: var(--text-secondary);
}

/* --- Launch CTA --- */
.launch-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.launch-card {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 36px;
  position: relative;
  overflow: hidden;
}

.launch-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--cta-gradient);
}

.launch-card h3 {
  font-size: 1.3rem;
  margin-bottom: 12px;
}

.launch-card p {
  font-size: 0.925rem;
  margin-bottom: 20px;
  line-height: 1.65;
}

/* --- Protocol Diagram --- */
.protocol-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin: 32px 0;
}

.protocol-actor {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 24px;
  text-align: center;
  position: relative;
}

.protocol-actor__icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.protocol-actor:nth-child(1) .protocol-actor__icon {
  background: rgba(0, 230, 118, 0.12);
  color: var(--accent-green);
  border: 1px solid rgba(0, 230, 118, 0.2);
}

.protocol-actor:nth-child(2) .protocol-actor__icon {
  background: rgba(0, 212, 255, 0.12);
  color: var(--accent-cyan);
  border: 1px solid rgba(0, 212, 255, 0.2);
}

.protocol-actor:nth-child(3) .protocol-actor__icon {
  background: rgba(179, 136, 255, 0.12);
  color: var(--accent-purple);
  border: 1px solid rgba(179, 136, 255, 0.2);
}

.protocol-actor:nth-child(4) .protocol-actor__icon {
  background: rgba(255, 145, 0, 0.12);
  color: var(--accent-orange);
  border: 1px solid rgba(255, 145, 0, 0.2);
}

.protocol-actor h4 {
  font-size: 1rem;
  margin-bottom: 6px;
}

.protocol-actor p {
  font-size: 0.825rem;
}

/* --- Best Practices List --- */
.best-practices-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  list-style: none;
}

.best-practices-list li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.best-practices-list li:hover {
  border-color: var(--border-secondary);
  color: var(--text-primary);
}

.best-practices-list li i {
  color: var(--accent-cyan);
  font-size: 1.1rem;
  flex-shrink: 0;
}

/* --- Support Cards --- */
.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 28px;
}

.support-card h4 {
  font-size: 1.05rem;
  margin-bottom: 8px;
}

.support-card p {
  font-size: 0.875rem;
  line-height: 1.6;
}

.support-card__items {
  list-style: none;
  margin-top: 12px;
}

.support-card__items li {
  padding: 6px 0;
  font-size: 0.85rem;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.support-card__items li i {
  color: var(--accent-cyan);
  font-size: 0.8rem;
}

/* --- Footer --- */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-primary);
  padding: 60px 0 40px;
}

.footer__grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer__brand p {
  font-size: 0.875rem;
  margin-top: 12px;
  max-width: 280px;
}

.footer__col h5 {
  color: var(--text-primary);
  margin-bottom: 16px;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.footer__col ul {
  list-style: none;
}

.footer__col ul li {
  margin-bottom: 10px;
}

.footer__col ul a {
  color: var(--text-secondary);
  font-size: 0.85rem;
  transition: color var(--transition-fast);
}

.footer__col ul a:hover {
  color: var(--text-primary);
}

.footer__bottom {
  padding-top: 24px;
  border-top: 1px solid var(--border-primary);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer__bottom p {
  font-size: 0.8rem;
  color: var(--text-tertiary);
}

/* --- Status Badge --- */
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  background: rgba(255, 145, 0, 0.1);
  border: 1px solid rgba(255, 145, 0, 0.2);
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent-orange);
}

.status-badge i {
  font-size: 0.7rem;
}

/* --- Feature list --- */
.feature-list {
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.feature-list li {
  display: flex;
  gap: 12px;
  padding: 16px;
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.feature-list li:hover {
  border-color: var(--border-secondary);
}

.feature-list li i {
  color: var(--accent-cyan);
  font-size: 1.1rem;
  flex-shrink: 0;
  margin-top: 2px;
}

.feature-list li strong {
  display: block;
  font-size: 0.9rem;
  margin-bottom: 4px;
  color: var(--text-primary);
}

.feature-list li span {
  font-size: 0.825rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .grid-3 {
    grid-template-columns: repeat(2, 1fr);
  }

  .protocol-diagram {
    grid-template-columns: repeat(2, 1fr);
  }

  .community-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .best-practices-list {
    grid-template-columns: repeat(2, 1fr);
  }

  .cli-setup__grid {
    grid-template-columns: 1fr;
  }

  .footer__grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  :root {
    --nav-height: 56px;
  }

  h1 { font-size: 2rem; }
  h2 { font-size: 1.5rem; }
  h3 { font-size: 1.2rem; }

  .hero {
    padding: 100px 0 60px;
  }

  .hero__ctas {
    flex-direction: column;
  }

  .nav__links {
    display: none;
    position: fixed;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-primary);
    flex-direction: column;
    padding: 16px 24px;
    gap: 0;
  }

  .nav__links.is-open {
    display: flex;
  }

  .nav__links a {
    padding: 12px 0;
  }

  .nav__search {
    display: none;
  }

  .nav__hamburger {
    display: flex;
  }

  .nav__login {
    display: none;
  }

  .grid-3, .grid-2 {
    grid-template-columns: 1fr;
  }

  .protocol-diagram {
    grid-template-columns: 1fr 1fr;
  }

  .community-grid {
    grid-template-columns: 1fr;
  }

  .launch-grid {
    grid-template-columns: 1fr;
  }

  .support-grid {
    grid-template-columns: 1fr;
  }

  .best-practices-list {
    grid-template-columns: 1fr;
  }

  .feature-list {
    grid-template-columns: 1fr;
  }

  .cli-setup {
    padding: 28px 20px;
  }

  .sidebar {
    transform: translateX(calc(-1 * var(--sidebar-width)));
  }

  .sidebar.is-mobile-open {
    transform: translateX(0);
  }

  .main-content {
    margin-left: 0;
  }

  .main-content__inner {
    padding: 32px 20px;
  }

  .footer__grid {
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }

  .footer__bottom {
    flex-direction: column;
    gap: 12px;
    text-align: center;
  }

  .section {
    padding: 56px 0;
  }
}

@media (max-width: 480px) {
  h1 { font-size: 1.65rem; }

  .protocol-diagram {
    grid-template-columns: 1fr;
  }

  .footer__grid {
    grid-template-columns: 1fr;
  }
}

/* ============================================
   CommerceForge Dev Docs — Design System
   ============================================ */

/* --- Design Tokens --- */
:root {
  /* Dark mode (default) */
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2333;
  --bg-card: #161b22;
  --bg-card-hover: #1c2531;
  --bg-code: #0d1117;
  --bg-sidebar: #0d1117;
  --bg-overlay: rgba(0, 0, 0, 0.6);

  --border-primary: #21262d;
  --border-secondary: #30363d;
  --border-accent: #475f91;

  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-tertiary: #6e7681;
  --text-inverse: #0d1117;

  --accent-blue: #475f91;
  --accent-blue-hover: #5a74b0;
  --accent-cyan: #00d4ff;
  --accent-cyan-hover: #33ddff;
  --accent-green: #00e676;
  --accent-green-dim: #00c853;
  --accent-purple: #b388ff;
  --accent-orange: #ff9100;
  --accent-pink: #ff4081;

  --cta-gradient: linear-gradient(135deg, #00e676, #00d4ff);

  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.5);
  --shadow-glow: 0 0 20px rgba(0, 230, 118, 0.15);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;

  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', SFMono-Regular, Consolas, 'Liberation Mono', Menlo, monospace;

  --sidebar-width: 260px;
  --sidebar-collapsed-width: 0px;
  --nav-height: 64px;
  --max-width: 1280px;

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: var(--accent-cyan);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--accent-cyan-hover);
}

img {
  max-width: 100%;
  display: block;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.25;
  color: var(--text-primary);
}

h1 { font-size: 2.75rem; letter-spacing: -0.02em; }
h2 { font-size: 2rem; letter-spacing: -0.015em; }
h3 { font-size: 1.5rem; letter-spacing: -0.01em; }
h4 { font-size: 1.25rem; }
h5 { font-size: 1rem; }
h6 { font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.05em; }

p {
  color: var(--text-secondary);
  line-height: 1.7;
}

.text-gradient {
  background: var(--cta-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* --- Container --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.container--narrow {
  max-width: 900px;
}

.container--wide {
  max-width: 1400px;
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-primary);
  z-index: 1000;
  display: flex;
  align-items: center;
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.nav__brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 1.125rem;
  color: var(--text-primary);
  text-decoration: none;
}

.nav__brand-icon {
  width: 32px;
  height: 32px;
  background: var(--cta-gradient);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  color: var(--text-inverse);
  font-weight: 800;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.nav__links a {
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color var(--transition-fast);
  position: relative;
}

.nav__links a:hover,
.nav__links a.active {
  color: var(--text-primary);
}

.nav__links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent-cyan);
  border-radius: 1px;
}

.nav__actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.nav__search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  color: var(--text-tertiary);
  font-size: 0.85rem;
  cursor: pointer;
  transition: border-color var(--transition-fast);
}

.nav__search:hover {
  border-color: var(--border-secondary);
}

.nav__search kbd {
  background: var(--bg-tertiary);
  border: 1px solid var(--border-primary);
  border-radius: 4px;
  padding: 1px 6px;
  font-family: var(--font-mono);
  font-size: 0.75rem;
}

.nav__login {
  padding: 7px 18px;
  background: transparent;
  border: 1px solid var(--border-secondary);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.nav__login:hover {
  background: var(--bg-tertiary);
  border-color: var(--text-tertiary);
}

.nav__hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
}

.nav__hamburger span {
  width: 22px;
  height: 2px;
  background: var(--text-primary);
  border-radius: 1px;
  transition: all var(--transition-fast);
}

/* --- Hero --- */
.hero {
  padding: 120px 0 80px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -25%;
  width: 150%;
  height: 200%;
  background: radial-gradient(ellipse at 30% 20%, rgba(0, 230, 118, 0.06) 0%, transparent 50%),
              radial-gradient(ellipse at 70% 80%, rgba(0, 212, 255, 0.04) 0%, transparent 50%);
  pointer-events: none;
}

.hero__content {
  position: relative;
  max-width: 720px;
}

.hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: rgba(0, 230, 118, 0.1);
  border: 1px solid rgba(0, 230, 118, 0.2);
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--accent-green);
  margin-bottom: 24px;
}

.hero__badge i {
  font-size: 0.9rem;
}

.hero h1 {
  margin-bottom: 20px;
}

.hero__subtitle {
  font-size: 1.15rem;
  line-height: 1.7;
  margin-bottom: 36px;
  max-width: 600px;
}

.hero__ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 22px;
  font-family: var(--font-sans);
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
  border: none;
  text-decoration: none;
}

.btn--primary {
  background: var(--accent-green);
  color: var(--text-inverse);
  box-shadow: var(--shadow-glow);
}

.btn--primary:hover {
  background: var(--accent-green-dim);
  color: var(--text-inverse);
  box-shadow: 0 0 30px rgba(0, 230, 118, 0.25);
}

.btn--secondary {
  background: transparent;
  border: 1px solid var(--border-secondary);
  color: var(--text-primary);
}

.btn--secondary:hover {
  background: var(--bg-tertiary);
  border-color: var(--text-tertiary);
  color: var(--text-primary);
}

.btn--ghost {
  background: transparent;
  color: var(--accent-cyan);
  padding: 10px 0;
}

.btn--ghost:hover {
  color: var(--accent-cyan-hover);
}

.btn--sm {
  padding: 7px 16px;
  font-size: 0.825rem;
}

/* --- Section --- */
.section {
  padding: 80px 0;
}

.section__header {
  margin-bottom: 48px;
}

.section__header h2 {
  margin-bottom: 12px;
}

.section__header p {
  font-size: 1.05rem;
  max-width: 600px;
}

.section--alt {
  background: var(--bg-secondary);
}

/* --- Cards --- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 28px;
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}

.card:hover {
  border-color: var(--border-secondary);
  background: var(--bg-card-hover);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card__icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 18px;
  font-size: 1.3rem;
}

.card__icon--green {
  background: rgba(0, 230, 118, 0.12);
  color: var(--accent-green);
  border: 1px solid rgba(0, 230, 118, 0.15);
}

.card__icon--cyan {
  background: rgba(0, 212, 255, 0.12);
  color: var(--accent-cyan);
  border: 1px solid rgba(0, 212, 255, 0.15);
}

.card__icon--purple {
  background: rgba(179, 136, 255, 0.12);
  color: var(--accent-purple);
  border: 1px solid rgba(179, 136, 255, 0.15);
}

.card__icon--orange {
  background: rgba(255, 145, 0, 0.12);
  color: var(--accent-orange);
  border: 1px solid rgba(255, 145, 0, 0.15);
}

.card__icon--pink {
  background: rgba(255, 64, 129, 0.12);
  color: var(--accent-pink);
  border: 1px solid rgba(255, 64, 129, 0.15);
}

.card__icon--blue {
  background: rgba(71, 95, 145, 0.2);
  color: var(--accent-blue-hover);
  border: 1px solid rgba(71, 95, 145, 0.25);
}

.card h3 {
  font-size: 1.15rem;
  margin-bottom: 10px;
}

.card p {
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 16px;
}

.card__link {
  font-size: 0.875rem;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.card__link i {
  font-size: 0.8rem;
  transition: transform var(--transition-fast);
}

.card:hover .card__link i {
  transform: translateX(3px);
}

/* Product cards - larger, with gradient accent */
.product-card {
  padding: 36px;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
}

.product-card--apps::before {
  background: linear-gradient(90deg, var(--accent-green), var(--accent-cyan));
}

.product-card--storefronts::before {
  background: linear-gradient(90deg, var(--accent-cyan), var(--accent-purple));
}

.product-card--agents::before {
  background: linear-gradient(90deg, var(--accent-purple), var(--accent-pink));
}

.product-card h3 {
  font-size: 1.35rem;
  margin-bottom: 12px;
}

/* Card grids */
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

/* --- Accordion --- */
.accordion {
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-card);
}

.accordion__item {
  border-bottom: 1px solid var(--border-primary);
}

.accordion__item:last-child {
  border-bottom: none;
}

.accordion__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 24px;
  background: transparent;
  border: none;
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition-fast);
  text-align: left;
}

.accordion__trigger:hover {
  background: var(--bg-card-hover);
}

.accordion__trigger i {
  transition: transform var(--transition-base);
  color: var(--text-tertiary);
}

.accordion__item.is-open .accordion__trigger {
  background: var(--bg-card-hover);
  color: var(--accent-cyan);
}

.accordion__item.is-open .accordion__trigger i {
  transform: rotate(180deg);
  color: var(--accent-cyan);
}

.accordion__body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base), padding var(--transition-base);
}

.accordion__item.is-open .accordion__body {
  max-height: 500px;
}

.accordion__content {
  padding: 0 24px 24px;
}

.accordion__step {
  display: flex;
  gap: 16px;
  margin-bottom: 20px;
}

.accordion__step-number {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--accent-cyan);
}

.accordion__step-text {
  padding-top: 3px;
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* --- Tabs (Package Manager) --- */
.tabs {
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-card);
}

.tabs__list {
  display: flex;
  border-bottom: 1px solid var(--border-primary);
  background: var(--bg-secondary);
}

.tabs__tab {
  padding: 12px 24px;
  background: transparent;
  border: none;
  color: var(--text-secondary);
  font-family: var(--font-sans);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
  position: relative;
}

.tabs__tab:hover {
  color: var(--text-primary);
  background: var(--bg-card-hover);
}

.tabs__tab.is-active {
  color: var(--accent-cyan);
}

.tabs__tab.is-active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent-cyan);
}

.tabs__panel {
  display: none;
  padding: 20px 24px;
}

.tabs__panel.is-active {
  display: block;
}

/* --- Code Block --- */
.code-block {
  background: var(--bg-code);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  padding: 16px 20px;
  font-family: var(--font-mono);
  font-size: 0.875rem;
  line-height: 1.7;
  color: var(--text-primary);
  overflow-x: auto;
  position: relative;
}

.code-block .prompt {
  color: var(--accent-green);
  user-select: none;
}

.code-block .command {
  color: var(--text-primary);
}

.code-block .comment {
  color: var(--text-tertiary);
}

.code-block__copy {
  position: absolute;
  top: 10px;
  right: 10px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  padding: 4px 10px;
  font-size: 0.75rem;
  cursor: pointer;
  transition: all var(--transition-fast);
  display: flex;
  align-items: center;
  gap: 4px;
}

.code-block__copy:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

/* --- CLI Setup Section --- */
.cli-setup {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  padding: 48px;
  border: 1px solid var(--border-primary);
}

.cli-setup__header {
  margin-bottom: 36px;
}

.cli-setup__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: start;
}

/* --- Sidebar Layout --- */
.layout {
  display: flex;
  min-height: calc(100vh - var(--nav-height));
  padding-top: var(--nav-height);
}

.sidebar {
  width: var(--sidebar-width);
  background: var(--bg-sidebar);
  border-right: 1px solid var(--border-primary);
  position: fixed;
  top: var(--nav-height);
  left: 0;
  bottom: 0;
  overflow-y: auto;
  transition: width var(--transition-base), transform var(--transition-base);
  z-index: 100;
  padding: 24px 0;
}

.sidebar.is-collapsed {
  width: var(--sidebar-collapsed-width);
  transform: translateX(calc(-1 * var(--sidebar-width)));
}

.sidebar__toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 20px;
  margin-bottom: 16px;
  background: none;
  border: none;
  color: var(--text-secondary);
  font-size: 0.8rem;
  cursor: pointer;
  font-family: var(--font-sans);
  transition: color var(--transition-fast);
  width: 100%;
}

.sidebar__toggle:hover {
  color: var(--text-primary);
}

.sidebar__section {
  margin-bottom: 24px;
}

.sidebar__section-title {
  padding: 0 20px;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-tertiary);
  margin-bottom: 8px;
}

.sidebar__link {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 20px;
  color: var(--text-secondary);
  font-size: 0.875rem;
  transition: all var(--transition-fast);
  text-decoration: none;
}

.sidebar__link:hover {
  color: var(--text-primary);
  background: var(--bg-secondary);
}

.sidebar__link.is-active {
  color: var(--accent-cyan);
  background: rgba(0, 212, 255, 0.06);
  border-right: 2px solid var(--accent-cyan);
}

.sidebar__link i {
  font-size: 1rem;
  width: 20px;
  text-align: center;
}

.main-content {
  flex: 1;
  margin-left: var(--sidebar-width);
  transition: margin-left var(--transition-base);
  min-width: 0;
}

.main-content.is-expanded {
  margin-left: var(--sidebar-collapsed-width);
}

.main-content__inner {
  max-width: 900px;
  margin: 0 auto;
  padding: 48px 40px;
}

/* --- Community Grid --- */
.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.community-card {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition-base);
  text-decoration: none;
  display: block;
}

.community-card:hover {
  border-color: var(--border-secondary);
  background: var(--bg-card-hover);
  transform: translateY(-2px);
}

.community-card i {
  font-size: 1.5rem;
  color: var(--accent-cyan);
  margin-bottom: 14px;
  display: block;
}

.community-card h4 {
  font-size: 0.95rem;
  margin-bottom: 6px;
  color: var(--text-primary);
}

.community-card p {
  font-size: 0.825rem;
  color: var(--text-secondary);
}

/* --- Launch CTA --- */
.launch-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.launch-card {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 36px;
  position: relative;
  overflow: hidden;
}

.launch-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--cta-gradient);
}

.launch-card h3 {
  font-size: 1.3rem;
  margin-bottom: 12px;
}

.launch-card p {
  font-size: 0.925rem;
  margin-bottom: 20px;
  line-height: 1.65;
}

/* --- Protocol Diagram --- */
.protocol-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin: 32px 0;
}

.protocol-actor {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 24px;
  text-align: center;
  position: relative;
}

.protocol-actor__icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.protocol-actor:nth-child(1) .protocol-actor__icon {
  background: rgba(0, 230, 118, 0.12);
  color: var(--accent-green);
  border: 1px solid rgba(0, 230, 118, 0.2);
}

.protocol-actor:nth-child(2) .protocol-actor__icon {
  background: rgba(0, 212, 255, 0.12);
  color: var(--accent-cyan);
  border: 1px solid rgba(0, 212, 255, 0.2);
}

.protocol-actor:nth-child(3) .protocol-actor__icon {
  background: rgba(179, 136, 255, 0.12);
  color: var(--accent-purple);
  border: 1px solid rgba(179, 136, 255, 0.2);
}

.protocol-actor:nth-child(4) .protocol-actor__icon {
  background: rgba(255, 145, 0, 0.12);
  color: var(--accent-orange);
  border: 1px solid rgba(255, 145, 0, 0.2);
}

.protocol-actor h4 {
  font-size: 1rem;
  margin-bottom: 6px;
}

.protocol-actor p {
  font-size: 0.825rem;
}

/* --- Best Practices List --- */
.best-practices-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  list-style: none;
}

.best-practices-list li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.best-practices-list li:hover {
  border-color: var(--border-secondary);
  color: var(--text-primary);
}

.best-practices-list li i {
  color: var(--accent-cyan);
  font-size: 1.1rem;
  flex-shrink: 0;
}

/* --- Support Cards --- */
.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 28px;
}

.support-card h4 {
  font-size: 1.05rem;
  margin-bottom: 8px;
}

.support-card p {
  font-size: 0.875rem;
  line-height: 1.6;
}

.support-card__items {
  list-style: none;
  margin-top: 12px;
}

.support-card__items li {
  padding: 6px 0;
  font-size: 0.85rem;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.support-card__items li i {
  color: var(--accent-cyan);
  font-size: 0.8rem;
}

/* --- Footer --- */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-primary);
  padding: 60px 0 40px;
}

.footer__grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer__brand p {
  font-size: 0.875rem;
  margin-top: 12px;
  max-width: 280px;
}

.footer__col h5 {
  color: var(--text-primary);
  margin-bottom: 16px;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.footer__col ul {
  list-style: none;
}

.footer__col ul li {
  margin-bottom: 10px;
}

.footer__col ul a {
  color: var(--text-secondary);
  font-size: 0.85rem;
  transition: color var(--transition-fast);
}

.footer__col ul a:hover {
  color: var(--text-primary);
}

.footer__bottom {
  padding-top: 24px;
  border-top: 1px solid var(--border-primary);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer__bottom p {
  font-size: 0.8rem;
  color: var(--text-tertiary);
}

/* --- Status Badge --- */
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  background: rgba(255, 145, 0, 0.1);
  border: 1px solid rgba(255, 145, 0, 0.2);
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent-orange);
}

.status-badge i {
  font-size: 0.7rem;
}

/* --- Feature list --- */
.feature-list {
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.feature-list li {
  display: flex;
  gap: 12px;
  padding: 16px;
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.feature-list li:hover {
  border-color: var(--border-secondary);
}

.feature-list li i {
  color: var(--accent-cyan);
  font-size: 1.1rem;
  flex-shrink: 0;
  margin-top: 2px;
}

.feature-list li strong {
  display: block;
  font-size: 0.9rem;
  margin-bottom: 4px;
  color: var(--text-primary);
}

.feature-list li span {
  font-size: 0.825rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .grid-3 {
    grid-template-columns: repeat(2, 1fr);
  }

  .protocol-diagram {
    grid-template-columns: repeat(2, 1fr);
  }

  .community-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .best-practices-list {
    grid-template-columns: repeat(2, 1fr);
  }

  .cli-setup__grid {
    grid-template-columns: 1fr;
  }

  .footer__grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  :root {
    --nav-height: 56px;
  }

  h1 { font-size: 2rem; }
  h2 { font-size: 1.5rem; }
  h3 { font-size: 1.2rem; }

  .hero {
    padding: 100px 0 60px;
  }

  .hero__ctas {
    flex-direction: column;
  }

  .nav__links {
    display: none;
    position: fixed;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-primary);
    flex-direction: column;
    padding: 16px 24px;
    gap: 0;
  }

  .nav__links.is-open {
    display: flex;
  }

  .nav__links a {
    padding: 12px 0;
  }

  .nav__search {
    display: none;
  }

  .nav__hamburger {
    display: flex;
  }

  .nav__login {
    display: none;
  }

  .grid-3, .grid-2 {
    grid-template-columns: 1fr;
  }

  .protocol-diagram {
    grid-template-columns: 1fr 1fr;
  }

  .community-grid {
    grid-template-columns: 1fr;
  }

  .launch-grid {
    grid-template-columns: 1fr;
  }

  .support-grid {
    grid-template-columns: 1fr;
  }

  .best-practices-list {
    grid-template-columns: 1fr;
  }

  .feature-list {
    grid-template-columns: 1fr;
  }

  .cli-setup {
    padding: 28px 20px;
  }

  .sidebar {
    transform: translateX(calc(-1 * var(--sidebar-width)));
  }

  .sidebar.is-mobile-open {
    transform: translateX(0);
  }

  .main-content {
    margin-left: 0;
  }

  .main-content__inner {
    padding: 32px 20px;
  }

  .footer__grid {
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }

  .footer__bottom {
    flex-direction: column;
    gap: 12px;
    text-align: center;
  }

  .section {
    padding: 56px 0;
  }
}

@media (max-width: 480px) {
  h1 { font-size: 1.65rem; }

  .protocol-diagram {
    grid-template-columns: 1fr;
  }

  .footer__grid {
    grid-template-columns: 1fr;
  }
}

raw_arguments.content:
/* ============================================
   CommerceForge Dev Docs — Design System
   ============================================ */

/* --- Design Tokens --- */
:root {
  /* Dark mode (default) */
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2333;
  --bg-card: #161b22;
  --bg-card-hover: #1c2531;
  --bg-code: #0d1117;
  --bg-sidebar: #0d1117;
  --bg-overlay: rgba(0, 0, 0, 0.6);

  --border-primary: #21262d;
  --border-secondary: #30363d;
  --border-accent: #475f91;

  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-tertiary: #6e7681;
  --text-inverse: #0d1117;

  --accent-blue: #475f91;
  --accent-blue-hover: #5a74b0;
  --accent-cyan: #00d4ff;
  --accent-cyan-hover: #33ddff;
  --accent-green: #00e676;
  --accent-green-dim: #00c853;
  --accent-purple: #b388ff;
  --accent-orange: #ff9100;
  --accent-pink: #ff4081;

  --cta-gradient: linear-gradient(135deg, #00e676, #00d4ff);

  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.5);
  --shadow-glow: 0 0 20px rgba(0, 230, 118, 0.15);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;

  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', SFMono-Regular, Consolas, 'Liberation Mono', Menlo, monospace;

  --sidebar-width: 260px;
  --sidebar-collapsed-width: 0px;
  --nav-height: 64px;
  --max-width: 1280px;

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: var(--accent-cyan);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--accent-cyan-hover);
}

img {
  max-width: 100%;
  display: block;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.25;
  color: var(--text-primary);
}

h1 { font-size: 2.75rem; letter-spacing: -0.02em; }
h2 { font-size: 2rem; letter-spacing: -0.015em; }
h3 { font-size: 1.5rem; letter-spacing: -0.01em; }
h4 { font-size: 1.25rem; }
h5 { font-size: 1rem; }
h6 { font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.05em; }

p {
  color: var(--text-secondary);
  line-height: 1.7;
}

.text-gradient {
  background: var(--cta-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* --- Container --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.container--narrow {
  max-width: 900px;
}

.container--wide {
  max-width: 1400px;
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-primary);
  z-index: 1000;
  display: flex;
  align-items: center;
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.nav__brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 1.125rem;
  color: var(--text-primary);
  text-decoration: none;
}

.nav__brand-icon {
  width: 32px;
  height: 32px;
  background: var(--cta-gradient);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  color: var(--text-inverse);
  font-weight: 800;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.nav__links a {
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color var(--transition-fast);
  position: relative;
}

.nav__links a:hover,
.nav__links a.active {
  color: var(--text-primary);
}

.nav__links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent-cyan);
  border-radius: 1px;
}

.nav__actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.nav__search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  color: var(--text-tertiary);
  font-size: 0.85rem;
  cursor: pointer;
  transition: border-color var(--transition-fast);
}

.nav__search:hover {
  border-color: var(--border-secondary);
}

.nav__search kbd {
  background: var(--bg-tertiary);
  border: 1px solid var(--border-primary);
  border-radius: 4px;
  padding: 1px 6px;
  font-family: var(--font-mono);
  font-size: 0.75rem;
}

.nav__login {
  padding: 7px 18px;
  background: transparent;
  border: 1px solid var(--border-secondary);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.nav__login:hover {
  background: var(--bg-tertiary);
  border-color: var(--text-tertiary);
}

.nav__hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
}

.nav__hamburger span {
  width: 22px;
  height: 2px;
  background: var(--text-primary);
  border-radius: 1px;
  transition: all var(--transition-fast);
}

/* --- Hero --- */
.hero {
  padding: 120px 0 80px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -25%;
  width: 150%;
  height: 200%;
  background: radial-gradient(ellipse at 30% 20%, rgba(0, 230, 118, 0.06) 0%, transparent 50%),
              radial-gradient(ellipse at 70% 80%, rgba(0, 212, 255, 0.04) 0%, transparent 50%);
  pointer-events: none;
}

.hero__content {
  position: relative;
  max-width: 720px;
}

.hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: rgba(0, 230, 118, 0.1);
  border: 1px solid rgba(0, 230, 118, 0.2);
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--accent-green);
  margin-bottom: 24px;
}

.hero__badge i {
  font-size: 0.9rem;
}

.hero h1 {
  margin-bottom: 20px;
}

.hero__subtitle {
  font-size: 1.15rem;
  line-height: 1.7;
  margin-bottom: 36px;
  max-width: 600px;
}

.hero__ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 22px;
  font-family: var(--font-sans);
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
  border: none;
  text-decoration: none;
}

.btn--primary {
  background: var(--accent-green);
  color: var(--text-inverse);
  box-shadow: var(--shadow-glow);
}

.btn--primary:hover {
  background: var(--accent-green-dim);
  color: var(--text-inverse);
  box-shadow: 0 0 30px rgba(0, 230, 118, 0.25);
}

.btn--secondary {
  background: transparent;
  border: 1px solid var(--border-secondary);
  color: var(--text-primary);
}

.btn--secondary:hover {
  background: var(--bg-tertiary);
  border-color: var(--text-tertiary);
  color: var(--text-primary);
}

.btn--ghost {
  background: transparent;
  color: var(--accent-cyan);
  padding: 10px 0;
}

.btn--ghost:hover {
  color: var(--accent-cyan-hover);
}

.btn--sm {
  padding: 7px 16px;
  font-size: 0.825rem;
}

/* --- Section --- */
.section {
  padding: 80px 0;
}

.section__header {
  margin-bottom: 48px;
}

.section__header h2 {
  margin-bottom: 12px;
}

.section__header p {
  font-size: 1.05rem;
  max-width: 600px;
}

.section--alt {
  background: var(--bg-secondary);
}

/* --- Cards --- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 28px;
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}

.card:hover {
  border-color: var(--border-secondary);
  background: var(--bg-card-hover);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card__icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 18px;
  font-size: 1.3rem;
}

.card__icon--green {
  background: rgba(0, 230, 118, 0.12);
  color: var(--accent-green);
  border: 1px solid rgba(0, 230, 118, 0.15);
}

.card__icon--cyan {
  background: rgba(0, 212, 255, 0.12);
  color: var(--accent-cyan);
  border: 1px solid rgba(0, 212, 255, 0.15);
}

.card__icon--purple {
  background: rgba(179, 136, 255, 0.12);
  color: var(--accent-purple);
  border: 1px solid rgba(179, 136, 255, 0.15);
}

.card__icon--orange {
  background: rgba(255, 145, 0, 0.12);
  color: var(--accent-orange);
  border: 1px solid rgba(255, 145, 0, 0.15);
}

.card__icon--pink {
  background: rgba(255, 64, 129, 0.12);
  color: var(--accent-pink);
  border: 1px solid rgba(255, 64, 129, 0.15);
}

.card__icon--blue {
  background: rgba(71, 95, 145, 0.2);
  color: var(--accent-blue-hover);
  border: 1px solid rgba(71, 95, 145, 0.25);
}

.card h3 {
  font-size: 1.15rem;
  margin-bottom: 10px;
}

.card p {
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 16px;
}

.card__link {
  font-size: 0.875rem;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.card__link i {
  font-size: 0.8rem;
  transition: transform var(--transition-fast);
}

.card:hover .card__link i {
  transform: translateX(3px);
}

/* Product cards - larger, with gradient accent */
.product-card {
  padding: 36px;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
}

.product-card--apps::before {
  background: linear-gradient(90deg, var(--accent-green), var(--accent-cyan));
}

.product-card--storefronts::before {
  background: linear-gradient(90deg, var(--accent-cyan), var(--accent-purple));
}

.product-card--agents::before {
  background: linear-gradient(90deg, var(--accent-purple), var(--accent-pink));
}

.product-card h3 {
  font-size: 1.35rem;
  margin-bottom: 12px;
}

/* Card grids */
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

/* --- Accordion --- */
.accordion {
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-card);
}

.accordion__item {
  border-bottom: 1px solid var(--border-primary);
}

.accordion__item:last-child {
  border-bottom: none;
}

.accordion__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 24px;
  background: transparent;
  border: none;
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition-fast);
  text-align: left;
}

.accordion__trigger:hover {
  background: var(--bg-card-hover);
}

.accordion__trigger i {
  transition: transform var(--transition-base);
  color: var(--text-tertiary);
}

.accordion__item.is-open .accordion__trigger {
  background: var(--bg-card-hover);
  color: var(--accent-cyan);
}

.accordion__item.is-open .accordion__trigger i {
  transform: rotate(180deg);
  color: var(--accent-cyan);
}

.accordion__body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base), padding var(--transition-base);
}

.accordion__item.is-open .accordion__body {
  max-height: 500px;
}

.accordion__content {
  padding: 0 24px 24px;
}

.accordion__step {
  display: flex;
  gap: 16px;
  margin-bottom: 20px;
}

.accordion__step-number {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--accent-cyan);
}

.accordion__step-text {
  padding-top: 3px;
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* --- Tabs (Package Manager) --- */
.tabs {
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-card);
}

.tabs__list {
  display: flex;
  border-bottom: 1px solid var(--border-primary);
  background: var(--bg-secondary);
}

.tabs__tab {
  padding: 12px 24px;
  background: transparent;
  border: none;
  color: var(--text-secondary);
  font-family: var(--font-sans);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
  position: relative;
}

.tabs__tab:hover {
  color: var(--text-primary);
  background: var(--bg-card-hover);
}

.tabs__tab.is-active {
  color: var(--accent-cyan);
}

.tabs__tab.is-active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent-cyan);
}

.tabs__panel {
  display: none;
  padding: 20px 24px;
}

.tabs__panel.is-active {
  display: block;
}

/* --- Code Block --- */
.code-block {
  background: var(--bg-code);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  padding: 16px 20px;
  font-family: var(--font-mono);
  font-size: 0.875rem;
  line-height: 1.7;
  color: var(--text-primary);
  overflow-x: auto;
  position: relative;
}

.code-block .prompt {
  color: var(--accent-green);
  user-select: none;
}

.code-block .command {
  color: var(--text-primary);
}

.code-block .comment {
  color: var(--text-tertiary);
}

.code-block__copy {
  position: absolute;
  top: 10px;
  right: 10px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  padding: 4px 10px;
  font-size: 0.75rem;
  cursor: pointer;
  transition: all var(--transition-fast);
  display: flex;
  align-items: center;
  gap: 4px;
}

.code-block__copy:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

/* --- CLI Setup Section --- */
.cli-setup {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  padding: 48px;
  border: 1px solid var(--border-primary);
}

.cli-setup__header {
  margin-bottom: 36px;
}

.cli-setup__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: start;
}

/* --- Sidebar Layout --- */
.layout {
  display: flex;
  min-height: calc(100vh - var(--nav-height));
  padding-top: var(--nav-height);
}

.sidebar {
  width: var(--sidebar-width);
  background: var(--bg-sidebar);
  border-right: 1px solid var(--border-primary);
  position: fixed;
  top: var(--nav-height);
  left: 0;
  bottom: 0;
  overflow-y: auto;
  transition: width var(--transition-base), transform var(--transition-base);
  z-index: 100;
  padding: 24px 0;
}

.sidebar.is-collapsed {
  width: var(--sidebar-collapsed-width);
  transform: translateX(calc(-1 * var(--sidebar-width)));
}

.sidebar__toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 20px;
  margin-bottom: 16px;
  background: none;
  border: none;
  color: var(--text-secondary);
  font-size: 0.8rem;
  cursor: pointer;
  font-family: var(--font-sans);
  transition: color var(--transition-fast);
  width: 100%;
}

.sidebar__toggle:hover {
  color: var(--text-primary);
}

.sidebar__section {
  margin-bottom: 24px;
}

.sidebar__section-title {
  padding: 0 20px;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-tertiary);
  margin-bottom: 8px;
}

.sidebar__link {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 20px;
  color: var(--text-secondary);
  font-size: 0.875rem;
  transition: all var(--transition-fast);
  text-decoration: none;
}

.sidebar__link:hover {
  color: var(--text-primary);
  background: var(--bg-secondary);
}

.sidebar__link.is-active {
  color: var(--accent-cyan);
  background: rgba(0, 212, 255, 0.06);
  border-right: 2px solid var(--accent-cyan);
}

.sidebar__link i {
  font-size: 1rem;
  width: 20px;
  text-align: center;
}

.main-content {
  flex: 1;
  margin-left: var(--sidebar-width);
  transition: margin-left var(--transition-base);
  min-width: 0;
}

.main-content.is-expanded {
  margin-left: var(--sidebar-collapsed-width);
}

.main-content__inner {
  max-width: 900px;
  margin: 0 auto;
  padding: 48px 40px;
}

/* --- Community Grid --- */
.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.community-card {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition-base);
  text-decoration: none;
  display: block;
}

.community-card:hover {
  border-color: var(--border-secondary);
  background: var(--bg-card-hover);
  transform: translateY(-2px);
}

.community-card i {
  font-size: 1.5rem;
  color: var(--accent-cyan);
  margin-bottom: 14px;
  display: block;
}

.community-card h4 {
  font-size: 0.95rem;
  margin-bottom: 6px;
  color: var(--text-primary);
}

.community-card p {
  font-size: 0.825rem;
  color: var(--text-secondary);
}

/* --- Launch CTA --- */
.launch-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.launch-card {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 36px;
  position: relative;
  overflow: hidden;
}

.launch-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--cta-gradient);
}

.launch-card h3 {
  font-size: 1.3rem;
  margin-bottom: 12px;
}

.launch-card p {
  font-size: 0.925rem;
  margin-bottom: 20px;
  line-height: 1.65;
}

/* --- Protocol Diagram --- */
.protocol-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin: 32px 0;
}

.protocol-actor {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 24px;
  text-align: center;
  position: relative;
}

.protocol-actor__icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.protocol-actor:nth-child(1) .protocol-actor__icon {
  background: rgba(0, 230, 118, 0.12);
  color: var(--accent-green);
  border: 1px solid rgba(0, 230, 118, 0.2);
}

.protocol-actor:nth-child(2) .protocol-actor__icon {
  background: rgba(0, 212, 255, 0.12);
  color: var(--accent-cyan);
  border: 1px solid rgba(0, 212, 255, 0.2);
}

.protocol-actor:nth-child(3) .protocol-actor__icon {
  background: rgba(179, 136, 255, 0.12);
  color: var(--accent-purple);
  border: 1px solid rgba(179, 136, 255, 0.2);
}

.protocol-actor:nth-child(4) .protocol-actor__icon {
  background: rgba(255, 145, 0, 0.12);
  color: var(--accent-orange);
  border: 1px solid rgba(255, 145, 0, 0.2);
}

.protocol-actor h4 {
  font-size: 1rem;
  margin-bottom: 6px;
}

.protocol-actor p {
  font-size: 0.825rem;
}

/* --- Best Practices List --- */
.best-practices-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  list-style: none;
}

.best-practices-list li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.best-practices-list li:hover {
  border-color: var(--border-secondary);
  color: var(--text-primary);
}

.best-practices-list li i {
  color: var(--accent-cyan);
  font-size: 1.1rem;
  flex-shrink: 0;
}

/* --- Support Cards --- */
.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-md);
  padding: 28px;
}

.support-card h4 {
  font-size: 1.05rem;
  margin-bottom: 8px;
}

.support-card p {
  font-size: 0.875rem;
  line-height: 1.6;
}

.support-card__items {
  list-style: none;
  margin-top: 12px;
}

.support-card__items li {
  padding: 6px 0;
  font-size: 0.85rem;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.support-card__items li i {
  color: var(--accent-cyan);
  font-size: 0.8rem;
}

/* --- Footer --- */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-primary);
  padding: 60px 0 40px;
}

.footer__grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer__brand p {
  font-size: 0.875rem;
  margin-top: 12px;
  max-width: 280px;
}

.footer__col h5 {
  color: var(--text-primary);
  margin-bottom: 16px;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.footer__col ul {
  list-style: none;
}

.footer__col ul li {
  margin-bottom: 10px;
}

.footer__col ul a {
  color: var(--text-secondary);
  font-size: 0.85rem;
  transition: color var(--transition-fast);
}

.footer__col ul a:hover {
  color: var(--text-primary);
}

.footer__bottom {
  padding-top: 24px;
  border-top: 1px solid var(--border-primary);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer__bottom p {
  font-size: 0.8rem;
  color: var(--text-tertiary);
}

/* --- Status Badge --- */
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  background: rgba(255, 145, 0, 0.1);
  border: 1px solid rgba(255, 145, 0, 0.2);
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent-orange);
}

.status-badge i {
  font-size: 0.7rem;
}

/* --- Feature list --- */
.feature-list {
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.feature-list li {
  display: flex;
  gap: 12px;
  padding: 16px;
  background: var(--bg-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.feature-list li:hover {
  border-color: var(--border-secondary);
}

.feature-list li i {
  color: var(--accent-cyan);
  font-size: 1.1rem;
  flex-shrink: 0;
  margin-top: 2px;
}

.feature-list li strong {
  display: block;
  font-size: 0.9rem;
  margin-bottom: 4px;
  color: var(--text-primary);
}

.feature-list li span {
  font-size: 0.825rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .grid-3 {
    grid-template-columns: repeat(2, 1fr);
  }

  .protocol-diagram {
    grid-template-columns: repeat(2, 1fr);
  }

  .community-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .best-practices-list {
    grid-template-columns: repeat(2, 1fr);
  }

  .cli-setup__grid {
    grid-template-columns: 1fr;
  }

  .footer__grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  :root {
    --nav-height: 56px;
  }

  h1 { font-size: 2rem; }
  h2 { font-size: 1.5rem; }
  h3 { font-size: 1.2rem; }

  .hero {
    padding: 100px 0 60px;
  }

  .hero__ctas {
    flex-direction: column;
  }

  .nav__links {
    display: none;
    position: fixed;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-primary);
    flex-direction: column;
    padding: 16px 24px;
    gap: 0;
  }

  .nav__links.is-open {
    display: flex;
  }

  .nav__links a {
    padding: 12px 0;
  }

  .nav__search {
    display: none;
  }

  .nav__hamburger {
    display: flex;
  }

  .nav__login {
    display: none;
  }

  .grid-3, .grid-2 {
    grid-template-columns: 1fr;
  }

  .protocol-diagram {
    grid-template-columns: 1fr 1fr;
  }

  .community-grid {
    grid-template-columns: 1fr;
  }

  .launch-grid {
    grid-template-columns: 1fr;
  }

  .support-grid {
    grid-template-columns: 1fr;
  }

  .best-practices-list {
    grid-template-columns: 1fr;
  }

  .feature-list {
    grid-template-columns: 1fr;
  }

  .cli-setup {
    padding: 28px 20px;
  }

  .sidebar {
    transform: translateX(calc(-1 * var(--sidebar-width)));
  }

  .sidebar.is-mobile-open {
    transform: translateX(0);
  }

  .main-content {
    margin-left: 0;
  }

  .main-content__inner {
    padding: 32px 20px;
  }

  .footer__grid {
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }

  .footer__bottom {
    flex-direction: column;
    gap: 12px;
    text-align: center;
  }

  .section {
    padding: 56px 0;
  }
}

@media (max-width: 480px) {
  h1 { font-size: 1.65rem; }

  .protocol-diagram {
    grid-template-columns: 1fr;
  }

  .footer__grid {
    grid-template-columns: 1fr;
  }
}

